/**
 * `/credits` — reachable without a session (see `App.tsx`, it sits outside `AppLayout` the same
 * way `/login` does). Lists the self-hosted font and the main runtime libraries with their
 * licences, per IP-06. The full list of every production dependency (web + API) lives in
 * `THIRD_PARTY_NOTICES.md` at the repo root, generated by `scripts/third-party-notices.mjs`.
 */

interface CreditEntry {
  name: string
  license: string
  url: string
}

const FONTS: CreditEntry[] = [
  { name: 'Fraunces', license: 'SIL Open Font License 1.1', url: 'https://fonts.google.com/specimen/Fraunces' },
]

const LIBRARIES: CreditEntry[] = [
  { name: 'React', license: 'MIT', url: 'https://react.dev' },
  { name: 'React DOM', license: 'MIT', url: 'https://react.dev' },
  { name: 'React Router', license: 'MIT', url: 'https://reactrouter.com' },
  { name: 'Zustand', license: 'MIT', url: 'https://github.com/pmndrs/zustand' },
  { name: '@microsoft/signalr', license: 'MIT', url: 'https://github.com/dotnet/aspnetcore' },
  { name: 'Framer Motion', license: 'MIT', url: 'https://motion.dev' },
  { name: 'Radix UI', license: 'MIT', url: 'https://www.radix-ui.com' },
]

function CreditList({ entries }: { entries: CreditEntry[] }) {
  return (
    <ul className="flex flex-col gap-2">
      {entries.map((e) => (
        <li key={e.name} className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1 text-sm">
          <a
            href={e.url}
            target="_blank"
            rel="noreferrer"
            className="font-medium text-text hover:text-accent hover:underline"
          >
            {e.name}
          </a>
          <span className="text-text-muted">{e.license}</span>
        </li>
      ))}
    </ul>
  )
}

export function CreditsPage() {
  return (
    <div className="min-h-screen bg-surface px-4 py-6 text-text sm:px-6">
      <div className="mx-auto max-w-2xl">
        <header className="mb-6">
          <h1 className="text-2xl font-semibold">Credits</h1>
          <p className="mt-1 text-sm text-text-muted">Heliograph © 2026 Bailey Halliday.</p>
        </header>

        <section className="mb-6">
          <h2 className="mb-2 text-sm font-semibold text-text-muted uppercase">Font</h2>
          <CreditList entries={FONTS} />
        </section>

        <section className="mb-6">
          <h2 className="mb-2 text-sm font-semibold text-text-muted uppercase">Runtime libraries</h2>
          <CreditList entries={LIBRARIES} />
        </section>

        <p className="text-xs text-text-subtle">
          Full list of production dependencies and licence texts: THIRD_PARTY_NOTICES.md in the
          project repository.
        </p>
      </div>
    </div>
  )
}
